import numpy as np
def worst(f, xr, yr, n=300):
    xs = np.geomspace(*xr, n)
    ys = np.geomspace(*yr, n)
    minA=1e18; argA=None
    minB=1e18; argB=None
    for x in xs:
        fx=f(x)
        for y in ys:
            fy=f(y)
            A = 2*x**2+2*fy**2-(fx+y)**2
            B = (fx+y)**2-4*x*fy
            if A<minA: minA=A; argA=(x,y)
            if B<minB: minB=B; argB=(x,y)
    return minA,argA,minB,argB

for c in [1,2]:
    f=lambda x,c=c: x+c
    print('c=',c, worst(f,(1e-4,1e4),(1e-4,1e4)))
