import numpy as np

def f(x, d):
    return x+d

def check(d, N=400):
    xs = np.geomspace(1e-3, 1e3, N)
    ys = np.geomspace(1e-3, 1e3, N)
    worstA = 1e18
    worstB = 1e18
    for x in xs:
        fx = f(x,d)
        for y in ys:
            fy = f(y,d)
            A = 2*x**2+2*fy**2 - (fx+y)**2
            B = (fx+y)**2 - 4*x*fy
            if A < worstA:
                worstA = A; wa=(x,y)
            if B < worstB:
                worstB = B; wb=(x,y)
    return worstA, wa, worstB, wb

for d in [1, 0.5, 2, -0.1]:
    print(d, check(d))
